/**
 * Persisted document schema and versioned import/export format.
 *
 * An investigation stores everything needed to reproduce its analysis: the
 * tool, its full configuration, the simulation seed and trial count, the
 * assumptions, and — optionally — a summary of the last results. Raw sample
 * arrays are never persisted; they are regenerated by re-running with the
 * stored seed, which is both smaller and a stronger guarantee of
 * reproducibility.
 *
 * Imported files are untrusted. Every field is validated with a Zod schema
 * before it reaches the application, and unknown fields are stripped rather
 * than passed through.
 */
import { z } from 'zod';

/** Bumped when the stored shape changes in a way that needs migration. */
export const SCHEMA_VERSION = 1;
export const FORMAT_ID = 'orbis-chance.investigation';

export const TOOL_IDS = [
  'probability-basics',
  'event-relationships',
  'combinatorics',
  'repeated-trials',
  'bayes',
  'bayesian-updating',
  'distribution-explorer',
  'experiment',
  'simulation',
  'scenario',
  'sensitivity',
  'risk',
  'data-lab',
  'markov',
  // Added with the capability expansion. Each maps to an implemented screen;
  // there are still no placeholder destinations.
  'decision',
  'bayes-network',
  'reliability',
  'queueing',
  'survival',
  'bayesian-inference',
  'extremes',
  'regression',
  'distribution-fitting',
  'hypothesis-tests',
  'time-series',
  // Exposing engine modules that had no interface at all.
  'imprecise',
  'causal',
  'networks',
  'processes',
  'portfolio',
  'des',
  'information',
  'elicitation',
  'sequential',
  'gaussian-process',
  'state-filtering',
  'transforms',
  'stochastic-optimisation',
  'model-comparison',
  'quasi-monte-carlo',
  'hidden-markov',
  'copula',
] as const;
export type ToolId = (typeof TOOL_IDS)[number];

/**
 * A tool configuration may nest (variables hold parameter objects, a Markov
 * chain holds a matrix), but only a few levels deep. Validating arbitrary
 * nesting with a recursive schema overflows the stack on a hostile file of a
 * couple of kilobytes, surfacing as "Maximum call stack size exceeded" rather
 * than a validation message, so depth is checked iteratively first.
 */
export const MAX_CONFIG_DEPTH = 32;

function nestingDepth(value: unknown, limit: number): number {
  // Iterative so that depth itself cannot overflow the stack.
  let depth = 0;
  let level: unknown[] = [value];
  while (level.length) {
    depth++;
    if (depth > limit) return depth;
    const next: unknown[] = [];
    for (const item of level) {
      if (Array.isArray(item)) next.push(...item);
      else if (item !== null && typeof item === 'object') next.push(...Object.values(item as Record<string, unknown>));
    }
    level = next;
  }
  return depth;
}

const jsonValue: z.ZodType<unknown> = z
  .unknown()
  .superRefine((value, ctx) => {
    if (nestingDepth(value, MAX_CONFIG_DEPTH) > MAX_CONFIG_DEPTH) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: `the configuration is nested more than ${MAX_CONFIG_DEPTH} levels deep, which no tool produces`,
      });
      return;
    }
    const invalid = findInvalidJson(value);
    if (invalid) ctx.addIssue({ code: z.ZodIssueCode.custom, message: invalid });
  });

/** Reject values a tool configuration can never legitimately contain. */
function findInvalidJson(root: unknown): string | null {
  const queue: unknown[] = [root];
  let seen = 0;
  while (queue.length) {
    const value = queue.pop();
    if (++seen > 200_000) return 'the configuration contains more values than any tool produces';
    if (value === null) continue;
    switch (typeof value) {
      case 'string':
      case 'boolean':
        continue;
      case 'number':
        if (!Number.isFinite(value)) return 'the configuration contains a value that is not a finite number';
        continue;
      case 'object':
        if (Array.isArray(value)) queue.push(...value);
        else queue.push(...Object.values(value as Record<string, unknown>));
        continue;
      default:
        return `the configuration contains an unsupported value of type ${typeof value}`;
    }
  }
  return null;
}

export const resultSummarySchema = z.object({
  /** Short headline value, e.g. "0.3412" or "£12,400". */
  headline: z.string().max(200).optional(),
  label: z.string().max(200).optional(),
  /** Key figures worth keeping with the saved investigation. */
  figures: z.array(z.object({ label: z.string().max(200), value: z.string().max(200) })).max(40).optional(),
  computedAt: z.string().max(40).optional(),
  /** True when the stored figures came from a simulation (so a re-run reproduces them only with the same seed). */
  fromSimulation: z.boolean().optional(),
});
export type ResultSummary = z.infer<typeof resultSummarySchema>;

export const investigationSchema = z.object({
  id: z.string().min(1).max(64),
  name: z.string().min(1).max(200),
  description: z.string().max(4000).default(''),
  toolId: z.enum(TOOL_IDS),
  /** Tool-specific configuration. Validated again by the tool before use. */
  config: jsonValue,
  /** Simulation settings, when the tool runs simulations. */
  simulation: z
    .object({
      trials: z.number().int().min(1).max(2_000_000),
      seed: z.string().min(1).max(64),
      keepSamples: z.boolean().default(false),
    })
    .optional(),
  /** User-entered assumptions, kept alongside the model. */
  assumptions: z.array(z.string().max(2000)).max(50).default([]),
  tags: z.array(z.string().max(40)).max(20).default([]),
  resultSummary: resultSummarySchema.optional(),
  createdAt: z.string(),
  updatedAt: z.string(),
  /** Set when this investigation was created from a template or example. */
  origin: z.object({ kind: z.enum(['template', 'example', 'duplicate', 'import', 'blank']), ref: z.string().max(100).optional() }).optional(),
});
export type Investigation = z.infer<typeof investigationSchema>;

export const templateSchema = z.object({
  id: z.string().min(1).max(64),
  name: z.string().min(1).max(200),
  description: z.string().max(2000).default(''),
  toolId: z.enum(TOOL_IDS),
  config: jsonValue,
  simulation: investigationSchema.shape.simulation,
  category: z.string().max(60).default('Custom'),
  createdAt: z.string(),
  /** User-created templates are editable; built-in ones are not. */
  builtIn: z.boolean().default(false),
});
export type UserTemplate = z.infer<typeof templateSchema>;

export const preferencesSchema = z.object({
  theme: z.enum(['dark', 'light', 'system']).default('dark'),
  reducedMotion: z.boolean().default(false),
  /** Show textures as well as colour in charts, for colour-vision accessibility. */
  chartTextures: z.boolean().default(false),
  defaultTrials: z.number().int().min(1).max(2_000_000).default(50_000),
  /** Significant digits shown for numeric results. */
  significantDigits: z.number().int().min(2).max(12).default(6),
  /** Remember the last tool opened. */
  lastToolId: z.enum(TOOL_IDS).optional(),
  numberFormat: z.enum(['plain', 'grouped']).default('grouped'),
});
export type Preferences = z.infer<typeof preferencesSchema>;

export const DEFAULT_PREFERENCES: Preferences = preferencesSchema.parse({});

/** The exported file format: one investigation, or a bundle of several. */
export const exportFileSchema = z.object({
  format: z.literal(FORMAT_ID),
  formatVersion: z.number().int().min(1),
  exportedAt: z.string(),
  /** Application version that produced the file, for diagnostics. */
  application: z.string().max(80).optional(),
  investigations: z.array(investigationSchema).min(1).max(500),
  templates: z.array(templateSchema).max(500).optional(),
});
export type ExportFile = z.infer<typeof exportFileSchema>;

export interface ImportOutcome {
  investigations: Investigation[];
  templates: UserTemplate[];
  warnings: string[];
}

/**
 * Validate and migrate an imported file. Throws a descriptive Error when the
 * file cannot be used; never partially applies a malformed import.
 */
export function parseExportFile(text: string): ImportOutcome {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch (e) {
    const message = (e as Error).message;
    if (e instanceof RangeError || /call stack/i.test(message)) {
      throw new Error('This file is nested far too deeply to be read. An Orbis Chance export nests only a few levels, so this is not one.');
    }
    throw new Error(`This file is not valid JSON, so it cannot be an Orbis Chance export: ${message}`);
  }
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error(
      `This file does not contain an Orbis Chance export: its top level is ${Array.isArray(raw) ? 'an array' : raw === null ? 'null' : `a ${typeof raw}`}, but an export file is an object with a "format" field.`,
    );
  }
  const asRecord = raw as Record<string, unknown>;
  if (asRecord.format !== FORMAT_ID) {
    throw new Error(
      `This file is not an Orbis Chance investigation export. Expected a "format" field of "${FORMAT_ID}" but found ${JSON.stringify(asRecord.format ?? null)}.`,
    );
  }
  const version = asRecord.formatVersion;
  if (typeof version !== 'number' || !Number.isInteger(version) || version < 1) {
    throw new Error('The export file has a missing or invalid format version.');
  }
  if (version > SCHEMA_VERSION) {
    throw new Error(
      `This file was created by a newer version of Orbis Chance (format version ${version}; this version supports up to ${SCHEMA_VERSION}). Update the application, or export again from the newer version using an older format.`,
    );
  }
  const migrated = migrate(asRecord, version);
  const parsed = exportFileSchema.safeParse(migrated);
  if (!parsed.success) {
    const first = parsed.error.issues[0];
    throw new Error(
      `The export file is not valid: ${first.path.join('.') || '(root)'} — ${first.message}. No investigations were imported.`,
    );
  }
  const warnings: string[] = [];
  if (version < SCHEMA_VERSION) warnings.push(`The file used format version ${version} and was upgraded to version ${SCHEMA_VERSION} on import.`);
  const withSamples = parsed.data.investigations.filter((i) => i.simulation?.keepSamples);
  if (withSamples.length) {
    warnings.push(
      `${withSamples.length} investigation(s) store simulation settings only, not the raw simulated values. Re-running them with the saved seed reproduces the same results exactly.`,
    );
  }
  return { investigations: parsed.data.investigations, templates: parsed.data.templates ?? [], warnings };
}

/** Apply schema migrations in sequence. Currently version 1 is the first. */
function migrate(file: Record<string, unknown>, fromVersion: number): Record<string, unknown> {
  let current = { ...file };
  let v = fromVersion;
  // Future migrations go here, each bumping v by one.
  while (v < SCHEMA_VERSION) {
    v++;
    current = { ...current, formatVersion: v };
  }
  return current;
}

export function buildExportFile(investigations: Investigation[], templates: UserTemplate[] = [], appVersion = '1.0.0'): ExportFile {
  return {
    format: FORMAT_ID,
    formatVersion: SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    application: `Orbis Chance ${appVersion}`,
    investigations,
    templates: templates.length ? templates : undefined,
  };
}

/** Validate a single investigation that came from storage or an import. */
export function validateInvestigation(value: unknown): { ok: true; value: Investigation } | { ok: false; error: string } {
  const parsed = investigationSchema.safeParse(value);
  if (parsed.success) return { ok: true, value: parsed.data };
  const first = parsed.error.issues[0];
  return { ok: false, error: `${first.path.join('.') || '(root)'}: ${first.message}` };
}
